pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount1, uint96 amount2, address attacker, address other) public {
        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        vm.assume(attacker != address(this));
        vm.assume(other != attacker);
        vm.assume(other != address(this));
        vm.assume(attacker.code.length == 0);

        // Deploy re-entrant attacker that calls withdrawBalance on receive
        ReentrantAttacker reentrant = new ReentrantAttacker(c);
        address addrReentrant = address(reentrant);
        vm.assume(attacker != addrReentrant);
        vm.assume(other != addrReentrant);

        // Fund attacker and other
        vm.deal(attacker, amount1 + amount2);
        vm.deal(other, amount2);

        // Add to balance for attacker
        vm.prank(attacker);
        c.addToBalance{value: amount1}();

        // Add to balance for other
        vm.prank(other);
        c.addToBalance{value: amount2}();

        uint256 attackerBalanceBefore = c.getBalance(attacker);
        uint256 otherBalanceBefore = c.getBalance(other);
        uint256 totalDepositedAttacker = amount1; // only one deposit from attacker so far

        // Re-entrant attack: attacker sends a small amount to the attacker contract, 
        // which will call addToBalance to increase its own balance, then withdrawBalance calls back.
        vm.prank(attacker);
        reentrant.attack{value: amount2}(amount2);

        // After attack, attacker's balance must not exceed total deposited by attacker
        uint256 attackerBalanceAfter = c.getBalance(attacker);
        assertTrue(attackerBalanceAfter <= totalDepositedAttacker, "Attacker balance exceeds deposits");
    }
}

contract ReentrantAttacker {
    C target;
    uint256 attackAmount;
    bool attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 amount) external payable {
        attackAmount = amount;
        attacking = true;
        // Add to balance on target for this contract (msg.sender is this contract)
        target.addToBalance{value: amount}();
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Re-enter withdrawBalance
            target.withdrawBalance();
        }
    }
}

