pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && withdrawAmount > 0);
        vm.assume(depositAmount >= withdrawAmount);

        // Deploy a reentrant attacker that will call addToBalance during withdrawal
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund the attacker and have it deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        attacker.deposit{value: depositAmount}();

        // Now have the attacker withdraw, which will re-enter addToBalance
        vm.prank(caller);
        attacker.withdraw(withdrawAmount);

        // After the withdrawal, the attacker's balance in C should be zero
        // (the reference contract enforces this; the buggy one may leave a non-zero balance)
        uint256 balanceAfter = c.getBalance(address(attacker));
        assertTrue(balanceAfter == 0);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 private amountToReenter;
    bool private isReentering;

    constructor(C _target) {
        target = _target;
    }

    function deposit() external payable {
        target.addToBalance{value: msg.value}();
    }

    function withdraw(uint256 amount) external {
        amountToReenter = amount;
        isReentering = false;
        target.withdrawBalance();
    }

    receive() external payable {
        if (!isReentering) {
            isReentering = true;
            // Re-enter addToBalance; in the buggy version this happens after the balance was set to 0
            target.addToBalance{value: amountToReenter}();
        }
    }
}

