import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Attacker {
    C target;
    uint256 prevBalance;
    uint256 msgValue;
    constructor(C _target) { target = _target; }
    receive() external payable {
        // Re-entrant withdraw: reset our balance to 0, then re-enter addToBalance
        target.withdrawBalance();
        target.addToBalance{value: msgValue}();
    }
    function establish(uint256 _prev, uint256 _value) external {
        prevBalance = _prev;
        msgValue = _value;
    }
}

contract InvMutTest is Test {
    C c;
    Attacker attacker;
    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }
    function testFuzz_property(uint96 initialBalance, uint96 depositAmount) public {
        uint256 ib = uint256(initialBalance);
        uint256 da = uint256(depositAmount);
        // Ensure deposit is non-zero to trigger re-entrancy
        vm.assume(da > 0);
        // Fund the attacker contract with its previous balance (pre-deposit state)
        vm.deal(address(attacker), ib + da);
        // Attacker first deposits its base balance
        vm.prank(address(attacker));
        c.addToBalance{value: ib}();
        // Attacker sets up for re-entrant scenario
        attacker.establish(ib, da);
        // Now, attacker initiates a deposit that triggers re-entrancy via receive()
        vm.prank(address(attacker));
        c.addToBalance{value: da}();
        // Invariant: after any addToBalance call, the caller's balance must reflect the correct addition
        uint256 postBalance = c.getBalance(address(attacker));
        assertEq(postBalance, ib + da, "Caller balance must be previous + msg.value");
    }
}

