contract InvMutTest is Test {
    C c;
    Attacker attacker;
    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }
    function testFuzz_property(uint96 amount, address other) public {
        vm.assume(other != address(0) && other != address(this) && other != address(attacker) && other != address(c));
        uint256 amt = uint256(amount);
        vm.assume(amt > 0);

        // Fund the attacker with some Ether
        vm.deal(address(attacker), 2 ether);

        // Also give some balance to an unrelated user for broader invariant check
        vm.deal(other, 1 ether);
        vm.prank(other);
        c.addToBalance{value: 1 ether}();

        // Attacker deposits first
        vm.prank(address(attacker));
        c.addToBalance{value: amt}();

        uint256 balanceBefore = c.getBalance(address(attacker));
        uint256 contractBalanceBefore = address(c).balance;

        // Trigger reentrancy: attacker withdraws, their receive() will re-enter addToBalance
        vm.prank(address(attacker));
        c.withdrawBalance();

        uint256 balanceAfter = c.getBalance(address(attacker));
        uint256 contractBalanceAfter = address(c).balance;

        // Invariant: attacker's balance cannot exceed the contract's current Ether balance
        // (since the contract's Ether must cover all balances, this is always true for the correct contract)
        assertTrue(balanceAfter <= contractBalanceAfter);
    }
}

